using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Threading.Tasks;using System.Windows.Forms;using System.Drawing;
namespace UrbanKaoz.DisplayRecorder {
 partial class MainForm {
  void InstallMenus15(){var menu=capture933.MontageView.menuA01;if(menu==null)return;var montage=menu.Items.Cast<ToolStripItem>().ToArray();Action update=()=>{menu.Items.Clear();menu.Visible=true;if(tabs933.SelectedIndex==2){menu.Items.AddRange(montage);return;}var file=new ToolStripMenuItem("Fichier");menu.Items.Add(file);if(tabs933.SelectedIndex==0){var convert=new ToolStripMenuItem("Convertir…");convert.Click+=delegate{using(var form=new ConverterForm15(path=>RecoverProject08(true,path)))form.ShowDialog(this);};file.DropDownItems.Add(convert);var sd=new ToolStripMenuItem("Carte SD Teensy…");sd.Click+=delegate{OpenSd905();};file.DropDownItems.Add(sd);}else{var micro=new ToolStripMenuItem("Paramètres micro…");micro.Click+=delegate{OpenAudio904();};file.DropDownItems.Add(micro);}};tabs933.SelectedIndexChanged+=delegate{update();};capture933.MontageView.VisibleChanged+=delegate{update();};update();}
 }
 sealed class ConverterForm15:Form {
  readonly RadioButton single=new RadioButton{Text="Un fichier",Checked=true,AutoSize=true},folder=new RadioButton{Text="Tous les projets d’un dossier",AutoSize=true};readonly CheckBox inject=new CheckBox{Text="Injecter ensuite : UKP = projet, PAT = patterns, SEQ = piste sélectionnée",AutoSize=true};readonly TextBox path=new TextBox{Width=580};readonly Label status=new Label{AutoSize=true,MaximumSize=new Size(600,0)};readonly Button run=new Button{Text="Convertir",AutoSize=true};readonly Action<string> injection;
  public ConverterForm15(Action<string> apply){injection=apply;Text="Convertir — Urban Kaoz VA01.15";ClientSize=new Size(650,310);StartPosition=FormStartPosition.CenterParent;var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(14),FlowDirection=FlowDirection.TopDown,WrapContents=false};Controls.Add(flow);flow.Controls.Add(single);flow.Controls.Add(folder);flow.Controls.Add(path);var browse=new Button{Text="Choisir…",AutoSize=true};flow.Controls.Add(browse);flow.Controls.Add(inject);flow.Controls.Add(run);flow.Controls.Add(status);folder.CheckedChanged+=delegate{inject.Enabled=!folder.Checked;if(folder.Checked)inject.Checked=false;};browse.Click+=delegate{if(folder.Checked){using(var d=new FolderBrowserDialog()){if(d.ShowDialog(this)==DialogResult.OK)path.Text=d.SelectedPath;}}else using(var d=new OpenFileDialog{Filter="Urban Kaoz|*.UKP;*.PAT;*.SEQ"}){if(d.ShowDialog(this)==DialogResult.OK)path.Text=d.FileName;}};run.Click+=async delegate{await ConvertAll();};}
  async Task ConvertAll(){run.Enabled=false;try{string input=Path.GetFullPath(path.Text);bool batch=folder.Checked;string[] files=batch?Directory.GetFiles(input).Where(p=>new[]{".ukp",".pat",".seq"}.Contains(Path.GetExtension(p).ToLowerInvariant())).OrderBy(p=>p).ToArray():new[]{input};if(files.Length==0)throw new IOException("Aucun projet compatible dans ce dossier.");string destination=batch?Path.Combine(input,"Convertis_VA01.15"):Path.GetDirectoryName(input);Directory.CreateDirectory(destination);string chosen=null;if(!batch){using(var d=new SaveFileDialog{Filter="Urban Kaoz|*"+Path.GetExtension(input),FileName=Path.GetFileNameWithoutExtension(input)+"_15"+Path.GetExtension(input),InitialDirectory=destination,OverwritePrompt=false}){if(d.ShowDialog(this)!=DialogResult.OK)return;chosen=d.FileName;}if(File.Exists(chosen))throw new IOException("Choisir un nouveau nom : le fichier existe déjà.");}int good=0;var errors=new System.Collections.Generic.List<string>();foreach(string source in files){string target=batch?Path.Combine(destination,Path.GetFileNameWithoutExtension(source)+"_15"+Path.GetExtension(source)):chosen;status.Text="Conversion : "+Path.GetFileName(source);try{await Task.Run(()=>ConvertOne(source,target));good++;}catch(Exception ex){errors.Add(Path.GetFileName(source)+" : "+ex.Message);}}status.Text=good+" fichier(s) converti(s), "+errors.Count+" échec(s). Originaux conservés.";if(errors.Count>0)Synkoz.ErrorR8.Show(this,string.Join(Environment.NewLine,errors),"Résultat de conversion");if(!batch&&good==1&&inject.Checked){injection(chosen);Close();}}catch(Exception ex){status.Text=ex.Message;Synkoz.ErrorR8.Show(this,ex.Message,"Erreur");}finally{run.Enabled=true;}}
  internal static void ConvertOne(string source,string target){string root=AppDomain.CurrentDomain.BaseDirectory;string script=Path.GetFullPath(Path.Combine(root,"..","Converter","convert14.py"));string python=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Python","pythoncore-3.14-64","python.exe");if(!File.Exists(script)||!File.Exists(python))throw new IOException("Convertisseur ou environnement Python absent de la livraison.");var start=new ProcessStartInfo(python,Quote(script)+" "+Quote(source)+" "+Quote(target)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=Process.Start(start)){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();process.WaitForExit();if(process.ExitCode!=0)throw new IOException(error.GetAwaiter().GetResult());output.GetAwaiter().GetResult();}}
  static string Quote(string value){return "\""+value.Replace("\"","\\\"")+"\"";}
 }
}
